do $$begin if current_database()<>'byus_clean'or inet_server_addr()is not null then raise exception 'Disposable Unixsocket byus_clean required';end if;end $$;
begin;
create function pg_temp.activity_assert(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',message;end if;raise notice 'PASS %',message;end $$;
create function pg_temp.activity_error(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected %',expected;end $$;
do $$declare owner uuid:='e9200000-0000-4000-8000-000000000001';member uuid:='e9200000-0000-4000-8000-000000000002';other uuid:='e9200000-0000-4000-8000-000000000003';page uuid:='e9200000-0000-4000-8000-000000000010';other_page uuid:='e9200000-0000-4000-8000-000000000011';admin uuid:=extensions.gen_random_uuid();ev uuid;mission uuid;reg uuid;submission uuid;application uuid;key uuid;qr text;result jsonb;payload jsonb;entry uuid;begin
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'did:privy:activity-owner','activity-owner@example.test'),(member,'did:privy:activity-member','activity-member@example.test'),(other,'did:privy:activity-other','activity-other@example.test');
 insert into public.admin_allowlist(id,email,role,active)values(admin,'activity-owner@example.test','admin',true);
 insert into public.group_pages(id,kind,name)values(page,'hobby','Local fixture'),(other_page,'brand','Other fixture');
 insert into public.group_memberships(page_id,app_user_id,role)values(page,owner,'owner'),(page,member,'member'),(other_page,other,'owner');
 payload:=jsonb_build_object('requestId',extensions.gen_random_uuid(),'title','Fixture running','description','Original description','imageUrl',null,'startsAt',clock_timestamp()-interval'1 hour','endsAt',clock_timestamp()+interval'1 hour','opensAt',clock_timestamp()-interval'1 day','closesAt',clock_timestamp()+interval'30 minutes','location','Fixture','capacity',1,'requiresApproval',true,'state','published');
 result:=public.group_activities_dispatch('event-save',owner,page,null,null,payload);ev:=(result#>>'{event,id}')::uuid;
 perform pg_temp.activity_assert(public.group_activities_dispatch('event-save',owner,page,null,null,payload)=result and(select count(*)from public.group_events where page_id=page)=1,'event creation replays once');
 perform pg_temp.activity_assert(public.group_activities_dispatch('event',null,page,ev)#>>'{event,official}'='false','pending official review is not official');
 perform pg_temp.activity_error(format('select public.group_activities_dispatch(''event-apply'',%L,%L,%L,null,%L)',other,page,ev,jsonb_build_object('requestId',extensions.gen_random_uuid())),'FORBIDDEN');
 result:=public.group_activities_dispatch('event-apply',member,page,ev,null,jsonb_build_object('requestId',extensions.gen_random_uuid()));
 perform pg_temp.activity_assert(result->>'status'='pending','approval-required application is pending');
 perform pg_temp.activity_error(format('select public.group_activities_dispatch(''event-ticket'',%L,%L,%L)',member,page,ev),'FORBIDDEN');
 select id into reg from public.group_event_registrations where event_id=ev and app_user_id=member;
 result:=public.group_activities_dispatch('event-review-participant',owner,page,ev,reg,jsonb_build_object('requestId',extensions.gen_random_uuid(),'action','confirm'));
 insert into public.group_memberships(page_id,app_user_id,role)values(page,other,'member');
 perform public.group_activities_dispatch('event-apply',other,page,ev,null,jsonb_build_object('requestId',extensions.gen_random_uuid()));
 perform pg_temp.activity_error(format('select public.group_activities_dispatch(''event-review-participant'',%L,%L,%L,%L,%L)',owner,page,ev,(select id from public.group_event_registrations where event_id=ev and app_user_id=other),jsonb_build_object('requestId',extensions.gen_random_uuid(),'action','confirm')),'CAPACITY');
 perform pg_temp.activity_assert((select count(*)from public.group_event_registrations where event_id=ev and status='confirmed')=1,'capacity prevents a second approval');
 qr:=public.group_activities_dispatch('event-ticket',member,page,ev)->>'qrPayload';
 delete from public.group_memberships where page_id=page and app_user_id=member;
 perform pg_temp.activity_error(format('select public.group_activities_dispatch(''event-ticket'',%L,%L,%L)',member,page,ev),'FORBIDDEN');
 insert into public.group_memberships(page_id,app_user_id,role)values(page,member,'member');
 perform pg_temp.activity_assert(result->>'status'='confirmed'and qr like'kyaa-event:%'and position(member::text in qr)=0,'confirmed ticket QR has no user identity');
 perform pg_temp.activity_error(format('select public.group_activities_dispatch(''event'',%L,%L,%L)',other,other_page,ev),'NOT_FOUND');
 perform pg_temp.activity_error(format('select public.group_activities_dispatch(''event-check-in'',%L,%L,%L,null,%L)',member,page,ev,jsonb_build_object('requestId',extensions.gen_random_uuid(),'qrPayload',qr)),'FORBIDDEN');
 result:=public.group_activities_dispatch('event-check-in',owner,page,ev,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'qrPayload',qr));
 perform pg_temp.activity_assert(result->>'checkedInAt'=public.group_activities_dispatch('event-check-in',owner,page,ev,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'qrPayload',qr))->>'checkedInAt','duplicate staff check-in preserves original timestamp');
 perform pg_temp.activity_error(format('select public.group_activities_dispatch(''event-review-write'',%L,%L,%L,null,%L)',member,page,ev,jsonb_build_object('requestId',extensions.gen_random_uuid(),'body','too early')),'FORBIDDEN');
 result:=public.group_activities_dispatch('official-submit',owner,page,ev,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'description','Original proof','sourceUrl','https://example.test/source'));application:=(result->>'id')::uuid;
 result:=public.group_activities_dispatch('official-review',owner,page,ev,application,jsonb_build_object('requestId',extensions.gen_random_uuid(),'action','request_changes','reason','More detail'),admin);
 perform pg_temp.activity_assert(public.group_activities_dispatch('admin-official-applications',owner,null,null,null,'{}',admin)#>>'{items,0,page_id}'=page::text,'official admin list carries real page context');
 perform pg_temp.activity_assert(result->>'status'='changes_requested'and(select description from public.group_official_event_applications where id=application)='Original proof','official supplementation keeps original submission');
 result:=public.group_activities_dispatch('official-submit',owner,page,ev,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'description','Supplemented proof','previousApplicationId',application));application:=(result->>'id')::uuid;
 perform public.group_activities_dispatch('official-review',owner,page,ev,application,jsonb_build_object('requestId',extensions.gen_random_uuid(),'action','approve'),admin);
 perform pg_temp.activity_assert(public.group_activities_dispatch('event',null,page,ev)#>>'{event,official}'='true','official badge follows platform approval');
 update public.group_events set ends_at=clock_timestamp()-interval'1 minute',closes_at=clock_timestamp()-interval'2 minutes'where id=ev;
 result:=public.group_activities_dispatch('event-review-write',member,page,ev,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'body','Original review'));
 perform pg_temp.activity_assert(result->>'status'='saved'and(select review_body from public.group_event_registrations where id=reg)='Original review','checked-in participant writes review after event');
 perform public.group_activities_dispatch('collection-save',owner,page,null,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'title','Hidden fixture','imageUrl',null,'externalUrl','https://example.test/item?keep=1#anchor','status','hidden'));
 perform pg_temp.activity_assert(jsonb_array_length(public.group_activities_dispatch('collections',null,page)->'items')=0 and jsonb_array_length(public.group_activities_dispatch('collections',owner,page)->'items')=1,'hidden collection only visible to page managers');
 payload:=jsonb_build_object('requestId',extensions.gen_random_uuid(),'title','Fixture mission','instructions','Describe an activity','imageUrl',null,'state','published');
 result:=public.group_activities_dispatch('mission-save',owner,page,null,null,payload);mission:=(result#>>'{mission,id}')::uuid;
 perform pg_temp.activity_error(format('select public.group_activities_dispatch(''mission-reward-policy'',%L,%L,%L,null,%L)',owner,page,mission,jsonb_build_object('requestId',extensions.gen_random_uuid(),'rewardPoints',50,'budgetPoints',50)),'FORBIDDEN');
 perform pg_temp.activity_assert(public.group_activities_dispatch('admin-missions',owner,null,null,null,'{}',admin)#>>'{items,0,pageId}'=page::text,'mission admin list includes persisted draft/public context');
 perform public.group_activities_dispatch('mission-reward-policy',owner,page,mission,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'rewardPoints',50,'budgetPoints',50),admin);
 result:=public.group_activities_dispatch('mission-submit',member,page,mission,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'body','Original proof'));submission:=(result->>'id')::uuid;
 update public.group_wallet_release set enabled=true,write_fenced=false,legacy_writers_verified=true,migration_evidence_sha256=repeat('c',64),rewards_start_on=current_date;
 key:=extensions.gen_random_uuid();payload:=jsonb_build_object('requestId',key,'action','approve','expectedSubmissionRevision',1);result:=public.group_activities_dispatch('mission-review',owner,page,mission,submission,payload);
 perform pg_temp.activity_assert(public.group_activities_dispatch('mission-review',owner,page,mission,submission,payload)=result and public.group_wallet_balance(member,'fan_point')=50,'approved configured mission credits common points once');
 entry:=public.group_wallet_post(member,'ticket',1,'group_exchange',extensions.gen_random_uuid());
 update public.app_users set status='disabled'where id=member;
 entry:=public.group_wallet_refund(member,1,extensions.gen_random_uuid());
 perform pg_temp.activity_assert(public.group_wallet_balance(member,'ticket')=2,'suspended user still receives protected cancellation refund');
 perform pg_temp.activity_error(format('select public.group_wallet_post(%L,''ticket'',-1,''group_raffle_entry'',%L)',member,extensions.gen_random_uuid()),'ACTIVE_ACCOUNT_REQUIRED');
 perform pg_temp.activity_assert(not has_function_privilege('service_role','public.group_wallet_refund(uuid,bigint,uuid)','EXECUTE'),'refund helper is not a client callable mint');
 perform public.group_activities_dispatch('mission-save',owner,page,null,null,jsonb_build_object('requestId',extensions.gen_random_uuid(),'title','Second persisted mission','instructions','Original instructions','imageUrl',null,'state','draft'));
 result:=public.group_activities_dispatch('admin-missions',owner,null,null,null,'{"limit":1}',admin);
 perform pg_temp.activity_assert(jsonb_array_length(result->'items')=1 and result->>'nextCursor'is not null,'admin mission first page has a real sentinel');
 result:=public.group_activities_dispatch('admin-missions',owner,null,null,null,jsonb_build_object('limit',1,'cursor',result->>'nextCursor'),admin);
 perform pg_temp.activity_assert(jsonb_array_length(result->'items')=1 and result->>'nextCursor'is null,'admin mission cursor reaches the final item');
end $$;
rollback;
